[$from,$to]=LegalController::dates();$d=LegalService::vat($cid,$from,$to);$groups=['taxed'=>'نرخ مثبت','zero'=>'نرخ صفر','unrated'=>'بدون نرخ / غیرمشمول ثبت‌شده'];$kinds=\Agah\Erp\Modules\Trade\InvoiceService::KINDS;
